<?php

declare(strict_types=1);

namespace Koravik\Districts\Health;

use Koravik\Platform\Database\Database;
use Koravik\Platform\Security\Security;
use RuntimeException;

final class HealthController
{
    public function __construct(private readonly Database $database){}
    public function handle(string $method,string $path):bool
    {
        if(!str_starts_with($path,'/health'))return false;$a=Security::account();if(!$a)return false;$account=(string)$a['id'];$s=new HealthService($this->database);
        if($method==='GET'&&$path==='/health'){$this->home($s->history($account),$s->trends($account));return true;}
        if($method==='POST'&&$path==='/health/checkins'){try{$this->csrf();$id=$s->save($account,$_POST);$_SESSION['flash']='Private wellbeing check-in saved.';$this->go('/health/checkins/'.$id);}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/health');}}
        if($method==='GET'&&preg_match('#^/health/checkins/([a-f0-9-]{36})$#',$path,$m)){$this->detail($s->get($account,$m[1]));return true;}
        if($method==='POST'&&preg_match('#^/health/checkins/([a-f0-9-]{36})$#',$path,$m)){try{$this->csrf();$s->save($account,$_POST,$m[1]);$_SESSION['flash']='Wellbeing check-in corrected.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/health/checkins/'.$m[1]);}
        if($method==='POST'&&preg_match('#^/health/checkins/([a-f0-9-]{36})/delete$#',$path,$m)){try{$this->csrf();$s->delete($account,$m[1]);$_SESSION['flash']='Wellbeing check-in deleted.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/health');}
        return false;
    }
    private function home(array $rows,array $trends):void{$cards='';foreach($rows as $r)$cards.='<article class="health-checkin-card"><p class="eyebrow">'.self::e((string)$r['observed_on']).'</p><h3>'.self::e(ucfirst((string)$r['feeling_word'])).'</h3><p>Energy '.(int)$r['energy_level'].' of 5</p><p class="meta">'.((bool)$r['share_derived_fact']?'Derived energy band sharing approved':'Entirely private').'</p><a href="/health/checkins/'.self::e((string)$r['id']).'">Review or correct</a></article>';$bands='';foreach(($trends['bands']??[]) as $band)$bands.='<li>'.self::e(ucfirst((string)$band['band'])).': '.(int)$band['count'].'</li>';$trend='<section class="health-trend-summary surface"><h2>Private 30-day trend</h2><dl><div><dt>Entries</dt><dd>'.(int)($trends['entries']??0).'</dd></div><div><dt>Average energy</dt><dd>'.self::e((string)($trends['avg_energy']??'Not enough yet')).'</dd></div><div><dt>Derived shares</dt><dd>'.(int)($trends['shared_count']??0).'</dd></div></dl><ul>'.($bands?:'<li>No trend bands yet.</li>').'</ul><p class="meta">This is a private summary for orientation only, not diagnosis, advice, streaks, or scoring.</p></section>';$body=$this->flash().'<section class="page-heading health-heading"><div><p class="eyebrow">Health · private wellbeing</p><h1>Notice how today feels.</h1><p>This is a personal observation, not a diagnosis, score, streak, or medical recommendation.</p></div></section>'.$trend.'<div class="health-layout"><form class="surface" method="post" action="/health/checkins">'.$this->csrfField().'<h2>New check-in</h2><label>Date<input type="date" name="observed_on" max="'.gmdate('Y-m-d').'" value="'.gmdate('Y-m-d').'" required></label><fieldset><legend>Energy right now</legend><div class="energy-scale">'.implode('',array_map(fn($n)=>'<label><input type="radio" name="energy_level" value="'.$n.'" required><span>'.$n.'</span></label>',range(1,5))).'</div><p class="meta">1 means very little available energy; 5 means plenty. Neither is success or failure.</p></fieldset><label>One feeling word<select name="feeling_word" required><option value="calm">Calm</option><option value="strained">Strained</option><option value="hopeful">Hopeful</option><option value="tired">Tired</option><option value="steady">Steady</option></select></label><label>Private note <span class="optional">Optional</span><textarea name="private_note" maxlength="1000"></textarea></label><label class="health-consent"><input type="checkbox" name="share_derived_fact" value="1"><span><strong>Share only a derived energy band</strong><small>Publishes low, steady, or full plus the date. The feeling word and private note remain excluded. No World or Companion receives it without a separate permission.</small></span></label><button class="button">Save private check-in</button></form><aside class="health-boundary"><h2>Health boundaries</h2><ul><li>Private by default.</li><li>No diagnosis or treatment advice.</li><li>No streaks, rewards, or shame.</li><li>Notes never enter the minimized event.</li><li>You may correct or delete entries.</li></ul></aside></div><section><h2>Recent check-ins</h2><div class="health-history">'.($cards?:'<p class="empty-state">No wellbeing check-ins yet.</p>').'</div></section>';$this->page('Health',$body);}
    private function detail(array $r):void{$id=self::e((string)$r['id']);$revisions='';foreach(($r['revisions']??[]) as $rev)$revisions.='<li>'.self::e(ucfirst((string)$rev['action'])).' · '.self::e((string)$rev['created_at']).' UTC</li>';$body=$this->flash().'<section class="page-heading"><div><p class="eyebrow">Health check-in</p><h1>'.self::e((string)$r['observed_on']).'</h1><p>Correct the observation without hiding that a revision occurred.</p></div><a href="/health">Health history</a></section><div class="health-layout"><form class="surface" method="post" action="/health/checkins/'.$id.'">'.$this->csrfField().'<label>Date<input type="date" name="observed_on" max="'.gmdate('Y-m-d').'" value="'.self::e((string)$r['observed_on']).'" required></label><label>Energy level<input type="number" name="energy_level" min="1" max="5" value="'.(int)$r['energy_level'].'" required></label><label>Feeling word<select name="feeling_word">'.implode('',array_map(fn($x)=>'<option value="'.$x.'"'.($r['feeling_word']===$x?' selected':'').'>'.ucfirst($x).'</option>',['calm','strained','hopeful','tired','steady'])).'</select></label><label>Private note<textarea name="private_note" maxlength="1000">'.self::e((string)$r['private_note']).'</textarea></label><label class="health-consent"><input type="checkbox" name="share_derived_fact" value="1"'.((bool)$r['share_derived_fact']?' checked':'').'><span><strong>Share only a derived energy band</strong><small>Private note and feeling word stay excluded.</small></span></label><button class="button">Save correction</button></form><aside class="health-boundary"><h2>Record detail and revision path</h2><p>Health owns this observation, its private note, and correction/deletion history.</p><ul>'.($revisions?:'<li>No revisions yet.</li>').'</ul><h2>Delete this observation</h2><p>Deletion removes the Health-owned record. Previously committed minimized events are historical evidence and are not rewritten.</p><form method="post" action="/health/checkins/'.$id.'/delete" onsubmit="return confirm(\'Delete this wellbeing check-in?\')">'.$this->csrfField().'<button class="quiet-button">Delete check-in</button></form></aside></div>';$this->page('Health check-in',$body);}
    private function csrf():void{if(!Security::verifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('Your session changed. Please try again.');}
    private function csrfField():string{return '<input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'">';}
    private function flash():string{$f=(string)($_SESSION['flash']??'');unset($_SESSION['flash']);return $f?'<div class="notice" role="status">'.self::e($f).'</div>':'';}
    private function go(string $to):never{header('Location: '.$to,true,303);exit;}
    private function page(string $title,string $body):void{echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).' · Koravik</title><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/health.css"></head><body><main id="main" class="page">'.$body.'</main></body></html>';}
    private static function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
}
